_S = lambda t, K='$B$1', pr='$B$2': (lambda r: f'=MAX(A{r}-{K},0)') if t == 'call' else (lambda r: f'=MAX({K}-A{r},0)')


def OPTX(sid, title, task, K, prem, typ, side, prices, values, y0, y1, yt, xt, hints=None):
    d = {'A1': 'מחיר מימוש (K)', 'B1': K, 'A2': 'פרמיה (Premium)', 'B2': prem, 'A4': 'מחיר בפקיעה', 'B4': 'תזרים (Payoff)', 'C4': 'רווח או הפסד (P&L)'}
    s = {}
    for i, p in enumerate(prices):
        r = 5 + i; d[f'A{r}'] = p
        core = _S(typ)(r)[1:]
        s[f'B{r}'] = '=' + core if side > 0 else f'=-{core}'
        s[f'C{r}'] = f'=B{r}-$B$2' if side > 0 else f'=B{r}+$B$2'
    last = 4 + len(prices)
    XLS(sid, title, title, task, d, s, [170, 140, 190], [4], values=values,
        hints=hints or ['קודם התזרים, בלי הפרמיה. לאחר מכן הרווח.', 'במחיר שלא כדאי בו לממש, התזרים 0. בנוסחה: MAX(...,0).', 'קבעו את K ואת הפרמיה עם ¤, כדי שתוכלו לגרור.'],
        remind={('call', 1): '<b>תזרים של Long Call</b> = $max(S_{T} − K, 0)$. באקסל: הפונקציה MAX, ובתוכה המחיר בפקיעה פחות מחיר המימוש, ואפס.<br><b>רווח</b> = תזרים פחות הפרמיה $c$.',
                ('call', -1): '<b>תזרים של Short Call</b> = $−max(S_{T} − K, 0)$. באקסל: מינוס לפני MAX, ובתוכה המחיר בפקיעה פחות מחיר המימוש, ואפס.<br><b>רווח</b> = תזרים ועוד הפרמיה $c$ שהכותב קיבל.',
                ('put', 1): '<b>תזרים של Long Put</b> = $max(K − S_{T}, 0)$. באקסל: הפונקציה MAX, ובתוכה מחיר המימוש פחות המחיר בפקיעה, ואפס.<br><b>רווח</b> = תזרים פחות הפרמיה $p$.',
                ('put', -1): '<b>תזרים של Short Put</b> = $−max(K − S_{T}, 0)$. באקסל: מינוס לפני MAX, ובתוכה מחיר המימוש פחות המחיר בפקיעה, ואפס.<br><b>רווח</b> = תזרים ועוד הפרמיה $p$ שהכותב קיבל.'}[(typ, side)],
        partial=['B5', 'C5'], chart=CH(['A5', f'A{last}'], [dict(y=['B5', f'B{last}'], c=PAYC, lab='תזרים'), dict(y=['C5', f'C{last}'], c=PNLC, lab='רווח', dy=22)], prices[0], prices[-1], y0, y1, xt, yt))


